function TxGetTransactionsByDate(divId, date) {
    $("#loading").show();
    if (date == undefined) date = new Date().format("YYYY-MM-DD","en");
    TxDateTransactions(date,function (resp) {
        $("#loading").hide();
        var data = resp.response.dateWiseTrans;
        var hasData = false;
        data.forEach(function (e) {
            e.transactionDate = e.transactionDate.asDate();
            if(e.transactionDate.format("YYYY-MM-DD", "en") === date){
                hasData = true;
                $("#no-data").addClass("hide");
                $("#"+divId).removeClass("hide");
                setPieData(divId, e);
            }
        });
        if(!hasData){
            $("#no-data").removeClass("hide");
            $("#"+divId).addClass("hide");
        }
    }, function (error) {
        $("#loading").hide();
    });
