var chartBarSelectedColor = "#104177";
var chartBarColor = "#4F89C9";
function TxGetTopTransactions(onResult, onError) {
    doHttpGet(apiConfig.projectionAPI + "/topNCounters?top=5", onResult, onError);
}
function TxDateTransactions(date, onResult, onError) {
    if (date == undefined) date = new Date().format("YYYY-MM-DD", "en");
    doHttpGet(apiConfig.projectionAPI + "dateWiseCounters?fromDate="+date+"&toDate="+date, onResult, onError);
}
function TxPlotChart(divId, data) {
    var labels = [];
    var values = [];
    var selected = data[data.length - 1];
    selected.color = chartBarSelectedColor;
    data.forEach(function (e) {
        labels.push(e.transactionDate.format("MMM - DD"));
        values.push({ y: e.procedureAmount, color: e.color, data: e });
    });
    Highcharts.chart(divId, {
        chart: {
            type: 'column',
            options3d: {
                enabled: false,
                alpha: 15,
                beta: 15,
                viewDistance: 10,
                depth: 10
            },
            backgroundColor: "rgba(255, 255, 255, 0)",
        },
        colors: [chartBarColor],
        exporting: { enabled: false },

        title: {
            text: null,
            align: 'left'
        },

        xAxis: {

            categories: labels,
            labels: {
                skew3d: true,
                style: {
                    fontSize: '14px',
                    color: '#748AA1'
                }
            },
        },

        yAxis: {
            className: 'highcharts-color-1',
            opposite: false,
            allowDecimals: false,
            min: 1,
            title: {
                text: null,
                skew3d: true,
                style: {
                    color: '#748AA1'
                }
            },
            labels: {
                style: {
                    fontSize: '14px',
                    color: '#748AA1'
                }
            },
            gridLineColor: 'rgba(255, 255, 255, 0.10)'
        },
        tooltip: {
            formatter: function () {
                return toSimpleCurrency(this.y);
            },
        },

        plotOptions: {
            column: {
                stacking: 'normal',
                depth: 10,
                borderRadiusTopLeft: 10,
                borderRadiusTopRight: 10,
                borderColor: 'rgba(255, 255, 255, 0)',
            },
            series: {
                pointWidth: 25
            }
        },

        series: [{
            showInLegend: false,
            name: 'Sales',
            data: values,
            events: {
                click: function (e) {
                    e.point.series.data.forEach(function (p) { p.update({ color: chartBarColor }) })
                    e.point.update({ color: chartBarSelectedColor });
                    onTxDataSelected(e.point.data);
                },
            },
        }]
    });
    onTxDataSelected(selected);
}
function onTxDataSelected(data) {
    document.getElementById("txTotal").textContent = toSimpleCurrency(data.procedureAmount, " ");
    document.getElementById("txTotalSale").textContent = toSimpleCurrency(data.saleAmount, " ");
    document.getElementById("txTotalMortg").textContent = toSimpleCurrency(data.mortgageAmount, " ");
    document.getElementById("txt-tr-date").textContent = data.transactionDate.format("dddd, DD MMMM YYYY");
}
