Highcharts.setOptions(Highcharts.theme);
function setPieData(container, data){
    var cd = [
        { name: AppStrings.sale, y: data.saleAmount },
        { name: AppStrings.mortgage, y: data.mortgageAmount },
        { name: AppStrings.other, y: data.otherAmount }
    ];
    if(chart == undefined) {
        Highcharts.setOptions({
            colors: Highcharts.map(Highcharts.getOptions().colors, function (color) {
                return {
                    radialGradient: {
                        cx: 0.5,
                        cy: 0.3,
                        r: 0.7
                    },
                    stops: [
                        [0, color],
                        [1, Highcharts.color(color).brighten(-0.3).get('rgb')] // darken
                    ]
                };
            })
        });
        chart  = Highcharts.chart(container, {
            exporting: {
                enabled: false,
            },
            chart: {
                plotBackgroundColor: null,
                plotBorderWidth: null,
                plotShadow: false,
                type: 'pie'
            },
            title: {
                text: AppStrings.total_transactions + ' ' + toSimpleCurrency(data.procedureAmount) + ' ' + AppStrings.aed,
                useHTML: true,
            },
            tooltip: {
                formatter: function() {
                    return this.point.name+  '<br/>'+ toSimpleCurrency(this.y)+ ' ' + AppStrings.aed  +'<br/><b>'+this.percentage.toFixed(2) +'%</b>'
                },
                useHTML: true,
            },
            accessibility: {
                point: {
                    valueSuffix: '%'
                }
            },
            plotOptions: {
                pie: {
                    allowPointSelect: false,
                    cursor: 'pointer',
                    dataLabels: {
                        enabled: true,
                        formatter: function (){
                            return this.point.name+  '<br/>'+ toSimpleCurrency(this.y)+ ' ' + AppStrings.aed +'<br/><b>'+this.percentage.toFixed(2) +'%</b>'
                        },
                        connectorColor: 'silver',
                        useHTML: true,
                    }
                }
            },
            series: [{
                name: 'Share',
                data: cd
            }]
        });
    }else {
        chart.series[0].update({data: cd}, true);
        chart.update({
            title: {
                text: AppStrings.total_transactions + ' ' + toSimpleCurrency(data.procedureAmount) + ' ' + AppStrings.aed,
            }
        })
    }

}
function TxGetTransactionsByDate(divId, date) {
    $("#loading").show();
    if (date == undefined) date = new Date().format("YYYY-MM-DD","en");
    TxDateTransactions(date,function (resp) {
        $("#loading").hide();
        var data = resp.response.dateWiseTrans;
        var hasData = false;
        data.forEach(function (e) {
            e.transactionDate = e.transactionDate.asDate();
            if(e.transactionDate.format("YYYY-MM-DD", "en") === date){
                hasData = true;
                $("#no-data").addClass("hide");
                $("#"+divId).removeClass("hide");
                setPieData(divId, e);
            }
        });
        if(!hasData){
            $("#no-data").removeClass("hide");
            $("#"+divId).addClass("hide");
        }
    }, function (error) {
        $("#loading").hide();
    });
}

