function populateHomeTransaction() {
    TxGetTopTransactions(function (resp) {
        var data = resp.response.dateWiseTrans;
        data.forEach(function (e) {
            e.transactionDate = e.transactionDate.asDate();
        });
        data = data.sort(function (a, b) {
            return a.transactionDate > b.transactionDate ? -1 : a.transactionDate < b.transactionDate ? 1 : 0
        });
        var dx = data[0];
        $("#tr-total-amount").text(toSimpleCurrency(dx.procedureAmount));
        $("#tr-date, #tr-date_card").text(dx.transactionDate.format("Do MMMM YYYY"));
        plotHomeGraph($("#tr-chart-sale"), "#FFAE00", dx.saleAmount, dx.procedureAmount);
        plotHomeGraph($("#tr-chart-mrt"), "#7DC855", dx.mortgageAmount, dx.procedureAmount);
        plotHomeGraph($("#tr-chart-other"), "#5A7BEF", dx.otherAmount, dx.procedureAmount);
        var date = dx.transactionDate.format("YYYY-MM-DD", "en");
        LoadTop(date, "sales");
        LoadTop(date, "mortgage");

    }, function (error) {

    });
}
function LoadTop(date, tType) {
    var c = $("#tr-top-" + tType);
    c.find(".loader").each(function (ix, x) {
        $(x).show();
    });
    var hf = function () {
        c.find(".loader").each(function (ix, x) {
            $(x).hide();
        });
    };
    TxGetTransactions(tType, date, date, AddTopFunction(tType, hf), function (e) {
        hf();
    });

}
function AddTopFunction(mode, hf) {
    return function (rsp) {
        hf();
        if (rsp.length <= 0) {

        } else {
            var areas = [];
            rsp.forEach(function (a) {
                a.name = LocaleUtil.getLocalValue(a.area);
                areas.push(a);
            });
            var htmltmpl = $("#tmpl-top-area-item").html();
            var areaTemplate = Handlebars.compile(htmltmpl);
            areas.slice(0, 3).forEach(function (a) {
                $("#tr-top-" + mode).append(areaTemplate(
                    {
                        name: LocaleUtil.getLocalValue(a.area),
                        value: toSimpleCurrency(a.worth)
                    }
                ));
            });

        }

    }
}
function plotHomeGraph(container, color, value, total) {
    var p = value / total * 100;
    container.find(".chart-percentage-value").text(p.toFixed(2) + " %");
    container.find(".chart-percentage").html(toSimpleCurrency(value));
    var cc = container.find(".chart-box")[0];
    Highcharts.chart(cc, {

        chart: {
            type: 'solidgauge',
            height: '90%',
            margin: 0
        },
        title: null,
        //{
            //text: "<div class='ch-title'>" + p.toFixed(2) + "% </div>",
            //text: "<div class='ch-title'>" + toSimpleCurrency(value) + "</div>",
            //verticalAlign: 'middle',
            //floating: true,
            //useHTML: true,
        //},
        exporting: { enabled: false },
        tooltip: { enabled: false },
        pane: {
            startAngle: 0,
            endAngle: 360,
            background: [{ // Track for Move
                outerRadius: '100%',
                innerRadius: '0',
                backgroundColor: Highcharts.color(color)
                    .setOpacity(0.1)
                    .get(),
                borderWidth: 0
            }]
        },
        yAxis: {
            min: 0,
            max: 100,
            lineWidth: 0,
            tickPositions: []
        },

        plotOptions: {
            solidgauge: {
                dataLabels: {
                    enabled: false
                },
                linecap: 'round',
                stickyTracking: true,
                rounded: true
            }
        },

        series: [
            {
                name: 'Move',
                data: [{
                    color: color,
                    radius: '110%',
                    innerRadius: '90%',
                    y: p
                }]
            },]
    });
}

